'use client';

import { Avatar, AvatarFallback, AvatarImage } from '@/registry/react/ui/avatar';
import { Tooltip, TooltipBody, TooltipTrigger } from '@/registry/react/ui/tooltip';
import styles from './expandable-avatar-group.module.css';

const members = [
  {
    name: 'Lena Ortiz',
    role: 'Product designer',
    image:
      'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=128&h=128&q=80',
  },
  {
    name: 'Amir Patel',
    role: 'Frontend engineer',
    image:
      'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=128&h=128&q=80',
  },
  {
    name: 'Mika Chen',
    role: 'Design engineer',
    image:
      'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=128&h=128&q=80',
  },
  {
    name: 'Noah Williams',
    role: 'Product manager',
    image:
      'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=128&h=128&q=80',
  },
  {
    name: 'Sofia Rossi',
    role: 'Brand designer',
    image:
      'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=128&h=128&q=80',
  },
  {
    name: 'Elliot Park',
    role: 'Researcher',
    image:
      'https://images.unsplash.com/photo-1527980965255-d3b416303d12?auto=format&fit=crop&w=128&h=128&q=80',
  },
  {
    name: 'Zoe Martin',
    role: 'Content designer',
    image:
      'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=128&h=128&q=80',
  },
];

export function ExpandableAvatarGroup() {
  return (
    <div className={styles.group} role="group" aria-label="Project team">
      {members.map((member) => (
        <Tooltip key={member.name} positioning={{ placement: 'top', gutter: 10 }} openDelay={120}>
          <TooltipTrigger asChild>
            <button
              className={styles.member}
              type="button"
              aria-label={`${member.name}, ${member.role}`}
            >
              <Avatar size="lg">
                <AvatarImage src={member.image} alt="" />
                <AvatarFallback>{member.name.slice(0, 1)}</AvatarFallback>
              </Avatar>
            </button>
          </TooltipTrigger>
          <TooltipBody className={styles.tooltip}>
            <strong>{member.name}</strong>
            <span>{member.role}</span>
          </TooltipBody>
        </Tooltip>
      ))}
    </div>
  );
}

.group {
  display: inline-flex;
  align-items: center;
  padding: var(--moduix-spacing-3);
}

.member {
  display: grid;
  position: relative;
  place-items: center;
  margin: 0;
  padding: 0;
  border: 2px solid var(--moduix-color-card);
  border-radius: var(--moduix-radius-full);
  background: transparent;
  cursor: pointer;
  transition:
    margin-inline-start 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    transform 180ms ease,
    box-shadow 180ms ease;

  &:not(:first-child) {
    margin-inline-start: calc(-1 * var(--moduix-spacing-3));
  }

  &:hover,
  &:focus-visible {
    z-index: 1;
    box-shadow: 0 0 0 3px var(--moduix-color-background);
    outline: none;
    transform: translateY(calc(-1 * var(--moduix-spacing-1))) scale(1.08);
  }
}

.member:is(:hover, :focus-visible) ~ .member {
  transform: translateX(var(--moduix-spacing-3));
}

.member:has(~ .member:is(:hover, :focus-visible)) {
  transform: translateX(calc(-1 * var(--moduix-spacing-3)));
}

.tooltip {
  display: grid;
  gap: 0.125rem;

  strong {
    font-weight: var(--moduix-weight-semibold);
  }

  span {
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
  }
}

@media (prefers-reduced-motion: reduce) {
  .member {
    transition: none;
  }
}
